                    .orElseThrow(() -> ApiException.conflict("commandKey 澶勭悊鍐茬獊: " + commandKey));
            return replay(committed, operation, requestHash, type);
        }
        T result = business.get();
        commandKeys.fillResponse(commandKey, 200, toJson(result));
