    if (req.briefingId() == null) throw badRequest("briefingId 不能为空");
    Incident incident = lockIncident(incidentKey);
    return runIdempotent(commandKey, "transfer_accept", hash(incidentKey, actor, req.briefingId().toString()), IncidentView.class, () -> {
        // existing status checks (RESOLVED/CLOSED → 422)
        IncidentTransfer pending = ... or 409;
        if (!pending.toCommander().equals(actor)) throw conflict(...);  // existing
        TransferBriefing briefing = briefings.findById(req.briefingId())
            .filter(b -> b.transferId() == pending.id())
            .orElseThrow(() -> conflict("简报不属于当前待接受的交接: " + req.briefingId()));
        TransferBriefing latest = findLatestByTransfer(pending.id());
        if (briefing.id() != latest.id()) throw conflict("简报版本已过期，需刷新并重新回读");
        // 必须已回读
        var readback = briefings.findReadback(briefing.id(), actor)
            .orElseThrow(() -> conflict("接班人尚未回读简报，不能接受交接"));
        // 内容仍当前
