```java
private Responses.BriefingContent buildContent(Incident incident, IncidentTransfer transfer, String note) {
    List<BriefingTaskItem> unfinished = tasks.listOpenByIncident(incident.id()).stream()
        .map(t -> new BriefingTaskItem(t.taskKey(), t.groupCode(), t.status().name()))
        .sorted(comparing taskKey)  // listOpenByIncident orders by id; sort by taskKey for determinism
        .toList();
    List<BriefingEscalationItem> unacked = escalations.listByIncident(incident.id()).stream()
        .filter(e -> e.status() == EscalationStatus.OPEN)
        .map(e -> new BriefingEscalationItem(e.id(), e.status().name(), e.triggeredAt(), e.deadlineAt()))
        .toList();
    return new BriefingContent(incident.incidentKey(), incident.status().name(),
        transfer.fromCommander(), transfer.toCommander(), note, unfinished, unacked);
}
