        jdbc.update(con -> {
            var ps = con.prepareStatement(
                    "INSERT INTO transfer_briefings (transfer_id, incident_id, version, content,"
                            + " digest, note, status, created_by, created_at)"
                            + " VALUES (?,?,?,?,?,?,?,?,?)",
